INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 10, 'theory', 'Quiz: def and fn');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 0, 'How do you replace a parameter with a default value (def f(x=5)) in Rust?', '["write fn f(x = 5)", "accept an Option and substitute with unwrap_or, or make a struct with defaults", "it is impossible and cannot be worked around", "write fn f(x?: i32)"]', 1, 'Parameters have no default values: use an Option, several functions, or the “builder” pattern.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 1, 'What replaces *args from Python?', '["the vararg! macro", "nothing: Rust cannot accept many values", "a slice parameter &[T] or a vector", "the rest keyword"]', 2, 'The function takes &[i32]: you can pass an array, a vector or part of a vector to it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 2, 'What does Rust make of 1 < x < 10?', '["a range check", "nothing: it is an error, you need x > 1 && x < 10 or (2..10).contains(&x)", "an equality check", "a comparison of the first and the last"]', 1, 'Rust has no comparison chains; write the conditions explicitly with && or use a range.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 3, 'What replaces Python exceptions in Rust?', '["the try! macro", "a catch block", "nothing, errors are ignored", "the Result type and the ? operator; panic! for the unrecoverable"]', 3, 'The function itself reports a possible error in the Result type, and ? passes it to the calling function.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 4, 'What does the list comprehension [x*2 for x in v if x>0] turn into?', '["v.iter().filter(|x| **x > 0).map(|x| x * 2).collect()", "a for loop with the yield keyword", "the list![…] macro", "you cannot do this in Rust"]', 0, 'An iterator chain compiles to an ordinary loop with no intermediate collections.');
